/// Returns the larger of two `u64` values using a “slow” loop-based method.
///
/// This mirrors the classic idea of subtracting 1 from both numbers until one
/// reaches 0; the number that still has remaining value is the larger.
/// (If both reach 0 together, they were equal.)
pub fn slow_max(a: u64, b: u64) -> u64 {
    // Working copies
    let mut x = a;
    let mut y = b;

    // Auxiliary counter: how much has been subtracted from each of x and y.
    let mut k: u64 = 0;

    // Loop “measure” for termination: min(x, y) strictly decreases each iteration.
    while x > 0 && y > 0 {
        // (1) x,y remain non-negative: guaranteed by u64 and the guard x>0 && y>0.
        // (2) k equals the amount subtracted so far.
        // (3) equal subtraction from both: we decrement both once per iteration.
        x -= 1;
        y -= 1;
        k += 1;
    }

    // At this point either x == 0 or y == 0 (or both).
    // Since x = a - k and y = b - k, the larger original value corresponds to
    // the side that has the larger remainder.
    if x > y { a } else { b }
}